// Agent-2 rec2 exact stationary-first-defect transfer, base 10, p=8,m=48.
// COMPUTED necessary overapproximation: arbitrarily chosen high descending carry,
// exact corrected lower carry from the lattice. A periodic orbit of larger
// width projects to one in every truncated k-column graph.
// Input generated by `agent2_rec2_data.py` from repository lat2.txt:
// 48 rows of 8 temporal lattice digits followed by 11 exterior rows.
// Usage: /tmp/agent2_rec2 /tmp/rec2_rows.txt j maxk [cap=2000000]
// Run j=0..47, maxk=29. If every cyclic two-sided core is empty for a j,
// every stationary first-defect centre for that j is excluded for all widths.

// For each k, compute indegree core of time-automaton on k consecutive columns.
// A (k+1)-cycle projects to a k-cycle, so lift only the surviving k indegree-core
// (which contains all cycles) by the next free digit. All other states can be excluded
// without a 19^(k+1) enumeration. x is fixed in spatial coordinates.
#include <bits/stdc++.h>
using namespace std;using u64=unsigned __int128;
int W[8][64], B[8][64]; int M=48,NB=11;
int gam[8]={1,0,1,0,1,0,1,0};
int K=3, X=120;
vector<u64> pow19;
int cell(int t,int x){return W[t%8][(x-NB+M*1000)%M];}
int acarry(int t,int x){for(int r=1;r<=60;r++){int v=cell(t,x-r);if(v!=9)return v>=10;}abort();}
int dcarry(int t,int x){for(int r=1;r<=60;r++){int v=cell(t,x+r);if(v!=9)return v>=10;}abort();}
u64 encode(int t,const int*z){u64 n=t;for(int i=K-1;i>=0;i--)n=19*n+z[i];return n;}
void decode(u64 n,int &t,int*z){for(int i=0;i<K;i++){z[i]=n%19;n/=19;}t=n;}
template<class F>void successors(u64 n, F emit){
 int t,v[64],dn[64],up[64],asc[65],ds[65],vv[64];decode(n,t,v);
 assert(t>=0&&t<8); if(v[0]==cell(t,X))return;
 asc[0]=acarry(t,X);
 for(int i=0;i<K;i++){up[i]=(v[i]+asc[i])%10;asc[i+1]=(v[i]+asc[i]>=10);}
 const int left=cell(t,X-1), ld=dcarry(t,X-1);
 for(int top=0;top<2;top++){
  ds[K]=top;
  for(int i=K-1;i>=0;i--){dn[i]=(v[i]+ds[i+1])%10;ds[i]=(v[i]+ds[i+1]>=10);}
  if((!gam[t] || left==9)&&ds[0]!=ld)continue;
  for(int i=0;i<K;i++){
   int second=gam[t]?(i==0?(left+ds[0])%10:dn[i-1]):dn[i];
   vv[i]=up[i]+second;
  }
  if(vv[0]!=cell(t+1,X))emit(encode((t+1)%8,vv));
 }
}
vector<u64> core(const vector<u64>& ids, uint64_t &edges){
// Sorted 64-bit key array; bounded memory even at 56M nodes.
 // This is slower per lookup than a hash table but needs only 12 bytes/node.
 const auto &lookup=ids;
 auto findid=[&](u64 key)->uint32_t {
  auto it=lower_bound(lookup.begin(),lookup.end(),key);
  if(it==lookup.end()||*it!=key)return UINT32_MAX;
  return (uint32_t)(it-lookup.begin());
 };
 vector<uint32_t> indeg(ids.size(),0);edges=0;
 for(u64 id:ids)successors(id,[&](u64 id2){
  uint32_t j=findid(id2);if(j==UINT32_MAX)return;
  ++indeg[j];++edges;
 });
 deque<uint32_t> q; for(uint32_t i=0;i<indeg.size();i++)if(!indeg[i])q.push_back(i);
 while(!q.empty()){
  uint32_t i=q.front();q.pop_front();
  successors(ids[i],[&](u64 id2){uint32_t j=findid(id2);if(j==UINT32_MAX)return;
   if(--indeg[j]==0)q.push_back(j);
  });
 }
 size_t keepCount=0;
 for(uint32_t d:indeg)if(d)++keepCount;
 vector<u64> left;left.reserve(keepCount);
 for(uint32_t i=0;i<ids.size();i++)if(indeg[i])left.push_back(ids[i]);
 return left;
}

// Repeatedly delete states with zero out-degree inside the already
// in-degree-pruned graph. Every periodic orbit survives both projections.
vector<u64> bidirectional_core(const vector<u64>& ids) {
 const uint32_t N=ids.size();
 auto idx=[&](u64 key)->uint32_t {
  auto it=lower_bound(ids.begin(),ids.end(),key);
  return it==ids.end()||*it!=key ? UINT32_MAX : uint32_t(it-ids.begin());
 };
 vector<uint32_t> incoming(N,0), outgoing(N,0);
 size_t M=0;
 for(uint32_t i=0;i<N;i++)successors(ids[i],[&](u64 key){
  auto j=idx(key);if(j!=UINT32_MAX){++incoming[j];++outgoing[i];++M;}
 });
 vector<uint32_t> offset(N+1,0);
 for(uint32_t i=0;i<N;i++)offset[i+1]=offset[i]+incoming[i];
 vector<uint32_t> cursor(offset.begin(),offset.end()), predecessors(M);
 for(uint32_t i=0;i<N;i++)successors(ids[i],[&](u64 key){
  auto j=idx(key);if(j!=UINT32_MAX)predecessors[cursor[j]++]=i;
 });
 vector<uint32_t>().swap(incoming);vector<uint32_t>().swap(cursor);
 deque<uint32_t> q;
 for(uint32_t i=0;i<N;i++)if(outgoing[i]==0)q.push_back(i);
 uint32_t peeled=0;
 while(!q.empty()){
  auto i=q.front();q.pop_front();++peeled;
  for(uint32_t pos=offset[i];pos<offset[i+1];pos++){
    auto j=predecessors[pos];if(--outgoing[j]==0)q.push_back(j);
  }
 }
 vector<u64> result;result.reserve(N-peeled);
 for(uint32_t i=0;i<N;i++)if(outgoing[i])result.push_back(ids[i]);
 return result;
}

int main(int argc,char**argv){if(argc<4){cerr<<"usage: data j maxk\n";return 2;}
 ifstream f(argv[1]);if(!f)return 2;for(int j=0;j<M;j++)for(int t=0;t<8;t++)f>>W[t][j];for(int j=0;j<NB;j++)for(int t=0;t<8;t++)f>>B[t][j];
 X=NB+2*M+stoi(argv[2]);int maxK=stoi(argv[3]);if(maxK>29)return 2;
 size_t limit=argc>4?stoull(argv[4]):2000000;
 pow19={1};for(int i=1;i<=maxK;i++)pow19.push_back(19*pow19.back());
 vector<u64> prev;
 for(K=2;K<=maxK;K++){
  vector<u64> nodes;
  if(K==2){nodes.reserve(8*18*19);
   for(int t=0;t<8;t++)for(int d1=0;d1<19;d1++)for(int d0=0;d0<19;d0++)if(d0!=cell(t,X)){nodes.push_back(u64(t)*361+u64(d1)*19+d0);}
  }else{
   nodes.reserve(prev.size()*19);
   for(u64 id:prev){u64 t=id/pow19[K-1], word=id%pow19[K-1];
    for(int high=0;high<19;high++)nodes.push_back((t*19+high)*pow19[K-1]+word);
   }
  }
  if(nodes.size()>limit){cout<<"j="<<argv[2]<<" k="<<K<<" CAPPED candidates="<<nodes.size()<<"\n"<<flush;break;}
  sort(nodes.begin(),nodes.end());
  auto start=chrono::steady_clock::now();uint64_t edges=0;
  vector<u64> surv=core(nodes,edges);
  size_t candidateCount=nodes.size();
  vector<u64>().swap(nodes); // avoid retaining potentially >1 GiB while building the reverse graph
  double seconds=chrono::duration<double>(chrono::steady_clock::now()-start).count();
  size_t indegreeCount=surv.size();
  auto bic=bidirectional_core(surv);
  vector<u64>().swap(surv);
  double allsecs=chrono::duration<double>(chrono::steady_clock::now()-start).count();
  cout<<"j="<<argv[2]<<" k="<<K<<" candidates="<<candidateCount<<" retained_edges="<<edges<<" indegree_core="<<indegreeCount<<" bicore="<<bic.size()<<" seconds="<<fixed<<setprecision(3)<<allsecs<<"\n"<<flush;
  prev.swap(bic);
  if(prev.empty())break;
 }
}